SELECT cs.canonical_smiles, sr.compound_name AS substrate_compound_name, pr.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m INNER JOIN compound_records sr ON m.substrate_record_id = sr.record_id INNER JOIN compound_records pr ON m.drug_record_id = pr.record_id INNER JOIN compound_structures cs ON sr.molregno = cs.molregno WHERE m.organism = 'Callithrix jacchus' ORDER BY cs.canonical_smiles ASC, sr.compound_name ASC, pr.compound_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
